.text
.global _start
_start:
MOV  R1, #0b11010010
MSR  CPSR_c, R1
LDR  SP, =0xFFFFFFFC
MOV  R0, #0b11010011
MSR  CPSR_c, R0
LDR  SP, =STACK_TOP
BL   SET_IRQs
BL   CONFIG_INTERVAL_TIMER
BL   CONFIG_KEYS
BL   CONFIG_PS2
BL   AUDIO_INIT
LDR  R0, =game_state
MOV  R1, #STATE_SPLASH
STR  R1, [R0]
LDR  R0, =reset_flag
MOV  R1, #0
STR  R1, [R0]
BL   ClearScreen
BL   DrawSplashScreen
MOV  R0, #SND_SPLASH
BL   BGM_Play
MOV  R1, #0b01010011
MSR  CPSR_c, R1
MainLoop:
LDR  R0, =game_state
LDR  R0, [R0]
CMP  R0, #STATE_SPLASH
BEQ  Splash_Loop
CMP  R0, #STATE_GAME_OVER
BEQ  GameOver_Loop
CMP  R0, #STATE_VICTORY
BEQ  Victory_Loop
WaitFrame:
LDR  R0, =frame_ready
LDR  R1, [R0]
CMP  R1, #0
BEQ  WaitFrame
MOV  R1, #0
STR  R1, [R0]
BL   CheckBulletVsInvaders
BL   CheckBulletVsBarriers
BL   CheckEBulletVsBarriers
BL   CheckEBulletVsCannon
BL   CheckEBullet2VsBarriers
BL   CheckEBullet2VsCannon
BL   CheckEBullet3VsBarriers
BL   CheckEBullet3VsCannon
BL   CheckEBullet4VsBarriers
BL   CheckEBullet4VsCannon
BL   CheckInvadersReachedBottom
BL   CheckCannonCollision
BL   CheckAllDead
BL   UpdateExplosions
BL   CheckPowerupVsCannon
BL   EraseAll
BL   ErasePowerup
BL   MoveCannon
BL   MoveBullet
BL   MoveEBullet
BL   MoveEBullet2
BL   MoveEBullet3
BL   MoveEBullet4
BL   MoveInvaders
BL   MaybeEnemyShoot
BL   MovePowerup
BL   DrawAll
BL   DrawBarriers
BL   DrawPowerup
BL   DrawUI
B    MainLoop
.ltorg
Splash_Loop:
LDR  R0, =reset_flag
LDR  R1, [R0]
CMP  R1, #1
BNE  Splash_Loop
MOV  R1, #0
LDR  R0, =reset_flag
STR  R1, [R0]
MOV  R0, #1
LDR  R1, =current_level
STR  R0, [R1]
LDR  R1, =lives
MOV  R0, #STARTING_LIVES
STR  R0, [R1]
BL   ClearScreen
BL   InitGame
MOV  R0, #SND_THEME
BL   BGM_Play
B    MainLoop
.ltorg
GameOver_Loop:
MOV  R0, #SND_GAMEOVER
BL   BGM_Play
BL   DrawGameOverScreen
GameOver_Wait:
LDR  R0, =reset_flag
LDR  R1, [R0]
CMP  R1, #1
BNE  GameOver_Wait
GameOver_Reset:
MOV  R0, #0
LDR  R1, =reset_flag
STR  R0, [R1]
MOV  R0, #1
LDR  R1, =current_level
STR  R0, [R1]
LDR  R1, =lives
MOV  R0, #STARTING_LIVES
STR  R0, [R1]
BL   ClearScreen
BL   InitGame
MOV  R0, #SND_THEME
BL   BGM_Play
B    MainLoop
.ltorg
Victory_Loop:
BL   DrawVictoryScreen
LDR  R0, =current_level
LDR  R1, [R0]
CMP  R1, #MAX_LEVEL
BGE  VL_FinalVictory
MOV  R2, #0
LDR  R3, =reset_flag
STR  R2, [R3]
VL_WaitNext:
LDR  R2, =reset_flag
LDR  R2, [R2]
CMP  R2, #1
BNE  VL_WaitNext
MOV  R2, #0
LDR  R3, =reset_flag
STR  R2, [R3]
ADD  R1, R1, #1
STR  R1, [R0]
BL   ClearScreen
BL   InitGame
LDR  R0, =game_state
MOV  R1, #STATE_PLAYING
STR  R1, [R0]
B    MainLoop
VL_FinalVictory:
BL   DrawFinalVictoryScreen
MOV  R1, #0b01010011
MSR  CPSR_c, R1
Victory_Wait:
LDR  R0, =reset_flag
LDR  R1, [R0]
CMP  R1, #1
BNE  Victory_Wait
MOV  R0, #0
LDR  R1, =reset_flag
STR  R0, [R1]
LDR  R0, =game_state
MOV  R1, #STATE_SPLASH
STR  R1, [R0]
BL   ClearScreen
BL   DrawSplashScreen
MOV  R0, #SND_SPLASH
BL   BGM_Play
B    MainLoop
.ltorg
InitGame:
PUSH {R0-R5, LR}
LDR  R0, =game_state
MOV  R1, #STATE_PLAYING
STR  R1, [R0]
LDR  R0, =current_level
LDR  R1, [R0]
CMP  R1, #0
MOVEQ R1, #1
STR  R1, [R0]
LDR  R0, =current_level
LDR  R1, [R0]
CMP  R1, #1
BNE  IG_KeepLives
LDR  R0, =score
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =lives
MOV  R1, #STARTING_LIVES
STR  R1, [R0]
LDR  R0, =pwup_collected
MOV  R1, #0
STR  R1, [R0]
IG_KeepLives:
LDR  R0, =invincible_frames
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =cannon_x
MOV  R1, #155
STR  R1, [R0]
LDR  R0, =prev_cannon_x
STR  R1, [R0]
LDR  R0, =inv_moved
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =pending_dir
STR  R1, [R0]
LDR  R0, =shot_cooldown
STR  R1, [R0]
LDR  R0, =bullet_x
LDR  R1, =BULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_bullet_x
STR  R1, [R0]
LDR  R0, =bullet_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_bullet_y
STR  R1, [R0]
LDR  R0, =ebullet_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_ebullet_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =ebullet_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_ebullet_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =ebullet2_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_ebullet2_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =ebullet2_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_ebullet2_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =ebullet3_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_ebullet3_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =ebullet3_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_ebullet3_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =ebullet4_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_ebullet4_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =ebullet4_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_ebullet4_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =eshoot_timer
MOV  R1, #ESHOOT_MIN
STR  R1, [R0]
LDR  R0, =rng_seed
LDR  R1, [R0]
CMP  R1, #0
MOVEQ R1, #37
STR  R1, [R0]
LDR  R0, =inv_offset_x
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =inv_offset_y
STR  R1, [R0]
LDR  R0, =inv_dir
MOV  R1, #1
STR  R1, [R0]
LDR  R0, =inv_move_counter
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_offset_x
STR  R1, [R0]
LDR  R0, =prev_offset_y
STR  R1, [R0]
LDR  R0, =inv_alive
LDR  R2, =inv_expl_timer
MOV  R1, #0
MOV  R3, #INV_ALIVE
MOV  R4, #0
IG_InitInv:
CMP  R1, #INV_COUNT
BGE  IG_Level3Pattern
STR  R3, [R0, R1, LSL #2]
STR  R4, [R2, R1, LSL #2]
ADD  R1, R1, #1
B    IG_InitInv
IG_Level3Pattern:
LDR  R5, =current_level
LDR  R5, [R5]
CMP  R5, #3
BNE  IG_InitBarriers
LDR  R0, =inv_alive
MOV  R4, #INV_DEAD
STR  R4, [R0, #0]
STR  R4, [R0, #4]
STR  R4, [R0, #36]
STR  R4, [R0, #40]
STR  R4, [R0, #44]
STR  R4, [R0, #84]
STR  R4, [R0, #132]
STR  R4, [R0, #172]
STR  R4, [R0, #176]
STR  R4, [R0, #180]
STR  R4, [R0, #212]
STR  R4, [R0, #216]
IG_InitBarriers:
LDR  R0, =barrier_blocks
MOV  R1, #0
MOV  R2, #BLOCK_FULL
IG_BarrierLoop:
CMP  R1, #BARRIER_BLOCKS
BGE  IG_InitPowerup
STR  R2, [R0, R1, LSL #2]
ADD  R1, R1, #1
B    IG_BarrierLoop
IG_InitPowerup:
LDR  R0, =pwup_x
LDR  R1, =PWUP_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_pwup_x
STR  R1, [R0]
LDR  R0, =pwup_y
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =prev_pwup_y
STR  R1, [R0]
LDR  R0, =pwup_type
MOV  R1, #PWUP_NONE
STR  R1, [R0]
LDR  R0, =pwup_kill_counter
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =current_level
LDR  R1, [R0]
CMP  R1, #3
MOVEQ R2, #13
BEQ  IG_SetSpeed
CMP  R1, #2
MOVEQ R2, #16
BEQ  IG_SetSpeed
MOV  R2, #20
IG_SetSpeed:
LDR  R0, =inv_move_every_val
STR  R2, [R0]
BL   DrawLevelBackground
IG_Done:
POP  {R0-R5, LR}
BX   LR
.ltorg
UpdateExplosions:
PUSH {R0-R7, LR}
LDR  R4, =inv_alive
LDR  R5, =inv_expl_timer
MOV  R0, #0
UE_Loop:
CMP  R0, #INV_COUNT
BGE  UE_Done
LDR  R1, [R4, R0, LSL #2]
CMP  R1, #INV_EXPLODING
BNE  UE_Next
LDR  R2, [R5, R0, LSL #2]
SUBS R2, R2, #1
STR  R2, [R5, R0, LSL #2]
BGT  UE_Next
PUSH {R0, R4-R5}
MOV  R6, R0
MOV  R1, #INV_COLS
BL   DivMod
LDR  R2, =inv_offset_x
LDR  R2, [R2]
MOV  R3, #INV_SPACING_X
MUL  R3, R1, R3
ADD  R3, R3, #INV_START_X
ADD  R3, R3, R2
LDR  R2, =inv_offset_y
LDR  R2, [R2]
MOV  R7, #INV_SPACING_Y
MUL  R7, R0, R7
ADD  R7, R7, #INV_START_Y
ADD  R7, R7, R2
MOV  R0, R3
MOV  R1, R7
LDR  R2, =bg_color
LDR  R2, [R2]
BL   EraseInvaderSprite
POP  {R0, R4-R5}
MOV  R1, #INV_DEAD
STR  R1, [R4, R0, LSL #2]
UE_Next:
ADD  R0, R0, #1
B    UE_Loop
UE_Done:
POP  {R0-R7, LR}
BX   LR
