UpdateHexDisplay:
PUSH {R4-R7, LR}
LDR  R6, =segment_table
MOV  R5, R0
MOV  R4, #0
MOV  R0, R5
MOV  R1, #10
BL   DivMod
LDR  R7, [R6, R1, LSL #2]
ORR  R4, R4, R7
MOV  R5, R0
MOV  R0, R5
MOV  R1, #10
BL   DivMod
LDR  R7, [R6, R1, LSL #2]
ORR  R4, R4, R7, LSL #8
MOV  R5, R0
MOV  R0, R5
MOV  R1, #10
BL   DivMod
LDR  R7, [R6, R1, LSL #2]
ORR  R4, R4, R7, LSL #16
MOV  R5, R0
MOV  R0, R5
MOV  R1, #10
BL   DivMod
LDR  R7, [R6, R1, LSL #2]
ORR  R4, R4, R7, LSL #24
LDR  R0, =HEX_BASE
STR  R4, [R0]
LDR  R5, =pwup_collected
LDR  R5, [R5]
CMP  R5, #9
MOVGT R5, #9
LDR  R7, [R6, R5, LSL #2]
LSL  R7, R7, #8
STR  R7, [R0, #16]
POP  {R4-R7, LR}
BX   LR
