DrawGameOverScreen:
PUSH {R0-R7, LR}
LDR  R0, =gameover_image
LDR  R1, =PIXBUF
MOV  R5, #0
DGO_RowLoop:
CMP  R5, #240
BGE  DGO_Done
MOV  R6, #0
LSL  R7, R5, #10
ADD  R7, R1, R7
DGO_ColLoop:
CMP  R6, #320
BGE  DGO_NextRow
LDR  R4, [R0]
STRH R4, [R7]
LSR  R4, R4, #16
STRH R4, [R7, #2]
ADD  R0, R0, #4
ADD  R7, R7, #4
ADD  R6, R6, #2
B    DGO_ColLoop
DGO_NextRow:
ADD  R5, R5, #1
B    DGO_RowLoop
DGO_Done:
POP  {R0-R7, LR}
BX   LR
