.ltorg
DrawBarriers:
PUSH {R0-R9, LR}
LDR  R9, =barrier_blocks
MOV  R8, #0
DBR_BarLoop:
CMP  R8, #BARRIER_COUNT
BGE  DBR_Done
CMP  R8, #0
MOVEQ R7, #BARRIER_X0
CMP  R8, #1
MOVEQ R7, #BARRIER_X1
CMP  R8, #2
MOVEQ R7, #BARRIER_X2
MOV  R6, #0
DBR_BlkLoop:
MOV  R0, #BARRIER_COLS
MOV  R1, #BARRIER_ROWS
MUL  R0, R0, R1
CMP  R6, R0
BGE  DBR_NextBar
MUL  R1, R8, R0
ADD  R0, R1, R6
LDR  R2, [R9, R0, LSL #2]
PUSH {R8}
MOV  R0, R6
MOV  R1, #BARRIER_COLS
BL   DivMod
POP  {R8}
MOV  R3, #BARRIER_BLOCK
MUL  R3, R1, R3
ADD  R3, R3, R7
MOV  R4, #BARRIER_BLOCK
MUL  R4, R0, R4
ADD  R4, R4, #BARRIER_Y
MOV  R0, #BARRIER_COLS
MOV  R1, #BARRIER_ROWS
MUL  R0, R0, R1
MUL  R1, R8, R0
ADD  R0, R1, R6
LDR  R2, [R9, R0, LSL #2]
CMP  R2, #3
LDREQ R5, =COLOR_GREEN
BEQ  DBR_DrawBlk
CMP  R2, #2
MOVEQ R5, #0x0300
ORREQ R5, R5, #0x00E0
BEQ  DBR_DrawBlk
CMP  R2, #1
MOVEQ R5, #0x0100
ORREQ R5, R5, #0x0060
BEQ  DBR_DrawBlk
MOV  R5, #COLOR_BLACK
DBR_DrawBlk:
PUSH {R6-R9}
MOV  R6, #0
DBR_BlkY:
CMP  R6, #BARRIER_BLOCK
BGE  DBR_BlkDone
MOV  R7, #0
DBR_BlkX:
CMP  R7, #BARRIER_BLOCK
BGE  DBR_BlkNextY
ADD  R0, R3, R7
ADD  R1, R4, R6
MOV  R2, R5
BL   WritePixelSafe
ADD  R7, R7, #1
B    DBR_BlkX
DBR_BlkNextY:
ADD  R6, R6, #1
B    DBR_BlkY
DBR_BlkDone:
POP  {R6-R9}
ADD  R6, R6, #1
B    DBR_BlkLoop
DBR_NextBar:
ADD  R8, R8, #1
B    DBR_BarLoop
DBR_Done:
POP  {R0-R9, LR}
BX   LR
.ltorg
DamageBarrierAt:
PUSH {R2-R9, LR}
MOV  R8, R0
MOV  R9, R1
CMP  R9, #BARRIER_Y
BLT  DBA_NoHit
MOV  R2, #BARRIER_ROWS
MOV  R3, #BARRIER_BLOCK
MUL  R2, R2, R3
ADD  R2, R2, #BARRIER_Y
CMP  R9, R2
BGE  DBA_NoHit
SUB  R1, R9, #BARRIER_Y
MOV  R0, R1
MOV  R1, #BARRIER_BLOCK
BL   DivMod
MOV  R6, R0
LDR  R7, =barrier_blocks
MOV  R5, #0
DBA_BarLoop:
CMP  R5, #BARRIER_COUNT
BGE  DBA_NoHit
CMP  R5, #0
MOVEQ R2, #BARRIER_X0
CMP  R5, #1
MOVEQ R2, #BARRIER_X1
CMP  R5, #2
MOVEQ R2, #BARRIER_X2
CMP  R8, R2
BLT  DBA_NextBar
MOV  R3, #BARRIER_COLS
MOV  R4, #BARRIER_BLOCK
MUL  R3, R3, R4
ADD  R3, R2, R3
CMP  R8, R3
BGE  DBA_NextBar
SUB  R0, R8, R2
MOV  R1, #BARRIER_BLOCK
BL   DivMod
MOV  R4, R0
MOV  R0, #BARRIER_COLS
MOV  R1, #BARRIER_ROWS
MUL  R0, R0, R1
MUL  R1, R5, R0
MOV  R0, #BARRIER_COLS
MUL  R2, R6, R0
ADD  R2, R2, R4
ADD  R2, R2, R1
LDR  R3, [R7, R2, LSL #2]
CMP  R3, #BLOCK_NONE
BEQ  DBA_NextBar
SUB  R3, R3, #1
STR  R3, [R7, R2, LSL #2]
CMP  R3, #BLOCK_NONE
BNE  DBA_Hit
DBA_Hit:
MOV  R0, #1
POP  {R2-R9, LR}
BX   LR
DBA_NextBar:
ADD  R5, R5, #1
B    DBA_BarLoop
DBA_NoHit:
MOV  R0, #0
POP  {R2-R9, LR}
BX   LR
