MaybeEnemyShoot:
PUSH {R0-R7, LR}
LDR  R2, =EBULLET_INACTIVE
LDR  R0, =ebullet_x
LDR  R1, [R0]
CMP  R1, R2
BEQ  MES_CheckTimer
LDR  R0, =ebullet2_x
LDR  R1, [R0]
CMP  R1, R2
BEQ  MES_CheckTimer
LDR  R0, =ebullet3_x
LDR  R1, [R0]
CMP  R1, R2
BEQ  MES_CheckTimer
LDR  R0, =ebullet4_x
LDR  R1, [R0]
CMP  R1, R2
BNE  MES_Done
MES_CheckTimer:
LDR  R0, =eshoot_timer
LDR  R1, [R0]
CMP  R1, #0
BGT  MES_Done
BL   NextRand
MOV  R1, #ESHOOT_RANGE
BL   DivMod
ADD  R1, R1, #ESHOOT_MIN
LDR  R0, =eshoot_timer
STR  R1, [R0]
LDR  R4, =inv_alive
MOV  R5, #0
MOV  R6, #0
MES_Count:
CMP  R5, #INV_COUNT
BGE  MES_CountDone
LDR  R0, [R4, R5, LSL #2]
CMP  R0, #INV_ALIVE
ADDEQ R6, R6, #1
ADD  R5, R5, #1
B    MES_Count
MES_CountDone:
CMP  R6, #0
BEQ  MES_Done
BL   NextRand
MOV  R1, R6
BL   DivMod
MOV  R5, #0
MOV  R7, #0
MES_Find:
CMP  R5, #INV_COUNT
BGE  MES_Done
LDR  R0, [R4, R5, LSL #2]
CMP  R0, #INV_ALIVE
BNE  MES_FindNext
CMP  R7, R1
BEQ  MES_Fire
ADD  R7, R7, #1
MES_FindNext:
ADD  R5, R5, #1
B    MES_Find
MES_Fire:
MOV  R0, R5
MOV  R1, #INV_COLS
BL   DivMod
LDR  R2, =inv_offset_x
LDR  R2, [R2]
MOV  R3, #INV_SPACING_X
MUL  R3, R1, R3
ADD  R3, R3, #INV_START_X
ADD  R3, R3, R2
ADD  R3, R3, #5
LDR  R2, =inv_offset_y
LDR  R2, [R2]
MOV  R6, #INV_SPACING_Y
MUL  R6, R0, R6
ADD  R6, R6, #INV_START_Y
ADD  R6, R6, R2
ADD  R6, R6, #CELL
LDR  R2, =EBULLET_INACTIVE
LDR  R0, =ebullet_x
LDR  R1, [R0]
CMP  R1, R2
BEQ  MES_UseBullet1
LDR  R0, =ebullet2_x
LDR  R1, [R0]
CMP  R1, R2
BEQ  MES_UseBullet2
LDR  R0, =ebullet3_x
LDR  R1, [R0]
CMP  R1, R2
BEQ  MES_UseBullet3
LDR  R0, =ebullet4_x
STR  R3, [R0]
LDR  R0, =ebullet4_y
STR  R6, [R0]
LDR  R0, =prev_ebullet4_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_ebullet4_y
MOV  R1, #0
STR  R1, [R0]
MOV  R0, #SND_BULLET
BL   SFX_Play
B    MES_Done
MES_UseBullet3:
LDR  R0, =ebullet3_x
STR  R3, [R0]
LDR  R0, =ebullet3_y
STR  R6, [R0]
LDR  R0, =prev_ebullet3_x
LDR  R1, =EBULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_ebullet3_y
