AUDIO_UPDATE:
PUSH {R0-R11, LR}
LDR  R11, =AUDIO_BASE
LDR  R10, [R11, #0x04]
LSR  R10, R10, #16
AND  R10, R10, #0xFF
CMP  R10, #0
BEQ  AU_Done
CMP  R10, #80
MOVGT R10, #80
LDR  R0, =snd_ptr
LDR  R4, [R0]
LDR  R0, =snd_size
LDR  R5, [R0]
LDR  R0, =sfx_ptr
LDR  R6, [R0]
LDR  R0, =sfx_size
LDR  R7, [R0]
AU_Loop:
CMP  R10, #0
BEQ  AU_SaveState
MOV  R8, #0
CMP  R5, #0
BLE  AU_NoBGM
LDRSH R8, [R4]
ADD  R4, R4, #2
SUB  R5, R5, #1
CMP  R5, #0
BLE  AU_ReloadBGM
B    AU_GetSFX
AU_ReloadBGM:
LDR  R0, =snd_id
LDR  R1, [R0]
CMP  R1, #0
BEQ  AU_NoBGM
LDR  R2, =audio_starts
LDR  R4, [R2, R1, LSL #2]
LDR  R2, =audio_sizes
LDR  R5, [R2, R1, LSL #2]
B    AU_GetSFX
AU_NoBGM:
MOV  R8, #0
AU_GetSFX:
MOV  R9, #0
CMP  R7, #0
BLE  AU_NoSFX
LDRSH R9, [R6]
ADD  R6, R6, #2
SUB  R7, R7, #1
B    AU_Mix
AU_NoSFX:
MOV  R9, #0
AU_Mix:
ADD  R8, R8, R9
LDR  R0, =32767
CMP  R8, R0
MOVGT R8, R0
LDR  R0, =-32768
CMP  R8, R0
MOVLT R8, R0
LSL  R8, R8, #16
STR  R8, [R11, #0x08]
STR  R8, [R11, #0x0C]
NOP
SUB  R10, R10, #1
B    AU_Loop
AU_SaveState:
LDR  R0, =snd_ptr
STR  R4, [R0]
LDR  R0, =snd_size
STR  R5, [R0]
LDR  R0, =sfx_ptr
STR  R6, [R0]
LDR  R0, =sfx_size
STR  R7, [R0]
AU_Done:
POP  {R0-R11, LR}
BX   LR
