CONFIG_GIC:
PUSH {LR}
MOV  R1, #1
BL   CONFIG_INTERRUPT
LDR  R0, =0xFFFEC100
LDR  R1, =0xFFFF
STR  R1, [R0, #0x04]
MOV  R1, #1
STR  R1, [R0]
LDR  R0, =0xFFFED000
STR  R1, [R0]
POP  {PC}
CONFIG_INTERRUPT:
PUSH {R4-R5, LR}
LSR  R4, R0, #3
BIC  R4, R4, #3
LDR  R2, =0xFFFED100
ADD  R4, R2, R4
AND  R2, R0, #0x1F
MOV  R5, #1
LSL  R2, R5, R2
LDR  R3, [R4]
ORR  R3, R3, R2
STR  R3, [R4]
BIC  R4, R0, #3
LDR  R2, =0xFFFED800
ADD  R4, R2, R4
AND  R2, R0, #0x3
ADD  R4, R2, R4
STRB R1, [R4]
POP  {R4-R5, PC}
.global SERVICE_IRQ
SERVICE_IRQ:
PUSH {R0-R7, LR}
LDR  R4, =0xFFFEC100
LDR  R5, [R4, #0x0C]
CMP  R5, #72
BNE  IRQ_Check_Keys
BL   TIMER_ISR
B    EXIT_IRQ
IRQ_Check_Keys:
CMP  R5, #73
BNE  IRQ_Check_PS2
BL   KEY_ISR
B    EXIT_IRQ
IRQ_Check_PS2:
CMP  R5, #79
BNE  IRQ_Unexpected
BL   PS2_ISR
B    EXIT_IRQ
IRQ_Unexpected:
STR  R5, [R4, #0x10]
POP  {R0-R7, LR}
SUBS PC, LR, #4
EXIT_IRQ:
STR  R5, [R4, #0x10]
POP  {R0-R7, LR}
SUBS PC, LR, #4
.global TIMER_ISR
TIMER_ISR:
PUSH {R4-R8, LR}
LDR  R0, =TIMER_BASE
MOV  R1, #0
STR  R1, [R0]
LDR  R0, =frame_ready
MOV  R1, #1
STR  R1, [R0]
LDR  R0, =shot_cooldown
LDR  R1, [R0]
CMP  R1, #0
SUBNE R1, R1, #1
STRNE R1, [R0]
LDR  R0, =invincible_frames
LDR  R1, [R0]
CMP  R1, #0
SUBNE R1, R1, #1
STRNE R1, [R0]
LDR  R0, =eshoot_timer
LDR  R1, [R0]
CMP  R1, #0
SUBGT R1, R1, #1
STRGT R1, [R0]
LDR  R0, =score
LDR  R4, [R0]
LDR  R0, =LEDR_BASE
STR  R4, [R0]
BL   AUDIO_UPDATE
BL   UpdatePowerupTimer
POP  {R4-R8, LR}
BX   LR
.global KEY_ISR
KEY_ISR:
PUSH {R4-R5, LR}
LDR  R0, =KEYS_BASE
LDR  R1, [R0, #0xC]
MOV  R2, #0xF
STR  R2, [R0, #0xC]
TST  R1, #0x1
BEQ  KI_Check_Key1
LDR  R2, =reset_flag
MOV  R4, #1
STR  R4, [R2]
B    KI_End
KI_Check_Key1:
TST  R1, #0x2
BEQ  KI_End
BL   FireBullet
KI_End:
POP  {R4-R5, LR}
BX   LR
.global PS2_ISR
PS2_ISR:
PUSH {R0-R4, LR}
LDR  R0, =PS2_BASE
LDR  R1, [R0]
TST  R1, #0x8000
BEQ  PS2_ISR_End
AND  R0, R1, #0xFF
CMP  R0, #0xF0
BEQ  PS2_SetF0
LDR  R1, =f0_flag_ps2
LDR  R2, [R1]
CMP  R2, #1
BEQ  PS2_ClearF0
CMP  R0, #0xE0
BEQ  PS2_SetE0
LDR  R1, =e0_flag_ps2
LDR  R2, [R1]
CMP  R2, #1
BEQ  PS2_Extended
CMP  R0, #0x29
BEQ  PS2_Fire
CMP  R0, #0x5A
BEQ  PS2_Fire
CMP  R0, #0x76
BEQ  PS2_Reset
B    PS2_ISR_End
PS2_SetF0:
LDR  R1, =f0_flag_ps2
MOV  R2, #1
STR  R2, [R1]
B    PS2_ISR_End
PS2_ClearF0:
LDR  R1, =f0_flag_ps2
MOV  R2, #0
STR  R2, [R1]
LDR  R1, =e0_flag_ps2
STR  R2, [R1]
CMP  R0, #0x6B
BEQ  PS2_StopDir
CMP  R0, #0x74
BEQ  PS2_StopDir
B    PS2_ISR_End
PS2_StopDir:
LDR  R1, =pending_dir
MOV  R2, #0
STR  R2, [R1]
B    PS2_ISR_End
PS2_SetE0:
LDR  R1, =f0_flag_ps2
MOV  R2, #0
STR  R2, [R1]
LDR  R1, =e0_flag_ps2
MOV  R2, #1
STR  R2, [R1]
B    PS2_ISR_End
PS2_Fire:
LDR  R1, =game_state
LDR  R1, [R1]
CMP  R1, #STATE_PLAYING
BNE  PS2_SetReset
BL   FireBullet
B    PS2_ISR_End
PS2_SetReset:
LDR  R1, =reset_flag
MOV  R2, #1
STR  R2, [R1]
B    PS2_ISR_End
PS2_Reset:
LDR  R1, =reset_flag
MOV  R2, #1
STR  R2, [R1]
B    PS2_ISR_End
PS2_Extended:
LDR  R1, =e0_flag_ps2
MOV  R2, #0
STR  R2, [R1]
CMP  R0, #0x6B
BEQ  PS2_Left
CMP  R0, #0x74
BEQ  PS2_Right
B    PS2_ISR_End
PS2_Left:
LDR  R2, =game_state
LDR  R2, [R2]
CMP  R2, #STATE_SPLASH
BEQ  PS2_SetReset
LDR  R1, =pending_dir
MOV  R2, #-1
STR  R2, [R1]
B    PS2_ISR_End
PS2_Right:
LDR  R2, =game_state
LDR  R2, [R2]
CMP  R2, #STATE_SPLASH
BEQ  PS2_SetReset
LDR  R1, =pending_dir
MOV  R2, #1
STR  R2, [R1]
B    PS2_ISR_End
PS2_ISR_End:
POP  {R0-R4, LR}
BX   LR
DrawSplashScreen:
PUSH {R0-R7, LR}
LDR  R0, =splash_image
LDR  R1, =PIXBUF
MOV  R5, #0
DSS_RowLoop:
CMP  R5, #240
BGE  DSS_Done
MOV  R6, #0
LSL  R7, R5, #10
ADD  R7, R1, R7
DSS_ColLoop:
CMP  R6, #320
BGE  DSS_NextRow
LDR  R4, [R0]
STRH R4, [R7]
LSR  R4, R4, #16
STRH R4, [R7, #2]
ADD  R0, R0, #4
ADD  R7, R7, #4
ADD  R6, R6, #2
B    DSS_ColLoop
DSS_NextRow:
ADD  R5, R5, #1
B    DSS_RowLoop
DSS_Done:
POP  {R0-R7, LR}
BX   LR
.ltorg
SpawnPowerup:
PUSH {R0-R3, LR}
MOV  R1, #PWUP_YELLOW
LDR  R0, =pwup_type
STR  R1, [R0]
LDR  R0, =pwup_x
STR  R6, [R0]
LDR  R0, =pwup_y
STR  R7, [R0]
LDR  R0, =prev_pwup_x
LDR  R1, =PWUP_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_pwup_y
MOV  R1, #0
STR  R1, [R0]
POP  {R0-R3, LR}
BX   LR
MovePowerup:
PUSH {R0-R3, LR}
LDR  R0, =pwup_x
LDR  R1, [R0]
LDR  R2, =PWUP_INACTIVE
CMP  R1, R2
BEQ  MP_Done
LDR  R0, =prev_pwup_x
STR  R1, [R0]
LDR  R0, =pwup_y
LDR  R3, [R0]
LDR  R0, =prev_pwup_y
STR  R3, [R0]
LDR  R0, =pwup_y
LDR  R1, [R0]
ADD  R1, R1, #PWUP_FALL_SPEED
CMP  R1, #HEIGHT
BGE  MP_Deactivate
STR  R1, [R0]
B    MP_Done
MP_Deactivate:
LDR  R0, =pwup_x
LDR  R1, =PWUP_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_pwup_x
STR  R1, [R0]
MP_Done:
POP  {R0-R3, LR}
BX   LR
ErasePowerup:
PUSH {R0-R4, LR}
LDR  R0, =prev_pwup_x
LDR  R0, [R0]
LDR  R1, =PWUP_INACTIVE
CMP  R0, R1
BEQ  EP_Done
LDR  R1, =prev_pwup_y
LDR  R1, [R1]
MOV  R2, #PWUP_SIZE
MOV  R3, #PWUP_SIZE
LDR  R4, =bg_color
LDR  R4, [R4]
BL   DrawRect
EP_Done:
POP  {R0-R4, LR}
BX   LR
DrawPowerup:
PUSH {R0-R6, LR}
LDR  R0, =pwup_x
LDR  R1, [R0]
LDR  R2, =PWUP_INACTIVE
CMP  R1, R2
BEQ  DPU_Done
LDR  R5, [R0]
LDR  R0, =pwup_y
LDR  R6, [R0]
LDR  R0, =pwup_type
LDR  R4, [R0]
CMP  R4, #PWUP_RED
MOVEQ R2, #COLOR_RED
BEQ  DPU_Draw
CMP  R4, #PWUP_BLUE
MOVEQ R2, #COLOR_BLUE
BEQ  DPU_Draw
CMP  R4, #PWUP_GREEN
MOVEQ R2, #COLOR_GREEN
BEQ  DPU_Draw
LDR  R2, =COLOR_YELLOW
DPU_Draw:
ADD  R0, R5, #1
ADD  R1, R6, #0
BL   WritePixelSafe
ADD  R0, R5, #2
BL   WritePixelSafe
ADD  R0, R5, #3
BL   WritePixelSafe
MOV  R3, #1
DPU_MidRows:
CMP  R3, #3
BGE  DPU_Bot
ADD  R0, R5, #0
ADD  R1, R6, R3
BL   WritePixelSafe
ADD  R0, R5, #1
BL   WritePixelSafe
ADD  R0, R5, #2
BL   WritePixelSafe
ADD  R0, R5, #3
BL   WritePixelSafe
ADD  R0, R5, #4
BL   WritePixelSafe
ADD  R3, R3, #1
B    DPU_MidRows
DPU_Bot:
ADD  R0, R5, #1
ADD  R1, R6, #3
BL   WritePixelSafe
ADD  R0, R5, #2
BL   WritePixelSafe
ADD  R0, R5, #3
BL   WritePixelSafe
DPU_Done:
POP  {R0-R6, LR}
BX   LR
CheckPowerupVsCannon:
PUSH {R0-R5, LR}
LDR  R0, =pwup_x
LDR  R1, [R0]
LDR  R2, =PWUP_INACTIVE
CMP  R1, R2
BEQ  CPC_Done
LDR  R2, =pwup_y
LDR  R2, [R2]
LDR  R3, =cannon_x
LDR  R3, [R3]
MOV  R4, #(CANNON_Y - 6)
CMP  R2, R4
BLT  CPC_Done
MOV  R4, #(CANNON_Y + 14)
CMP  R2, R4
BGT  CPC_Done
SUB  R4, R3, #6
CMP  R1, R4
BLT  CPC_Done
ADD  R4, R3, #24
CMP  R1, R4
BGT  CPC_Done
LDR  R0, =pwup_collected
LDR  R5, [R0]
ADD  R5, R5, #1
STR  R5, [R0]
LDR  R0, =pwup_type
LDR  R4, [R0]
CMP  R4, #PWUP_YELLOW
BNE  CPC_Activate
LDR  R0, =lives
LDR  R5, [R0]
CMP  R5, #5
BGE  CPC_Deactivate
ADD  R5, R5, #1
STR  R5, [R0]
B    CPC_Deactivate
CPC_Activate:
LDR  R0, =pwup_active
STR  R4, [R0]
LDR  R0, =pwup_timer
LDR  R1, =PWUP_DURATION
STR  R1, [R0]
CMP  R4, #PWUP_RED
BNE  CPC_Deactivate
LDR  R0, =pwup_penetrate_count
MOV  R1, #2
STR  R1, [R0]
CPC_Deactivate:
LDR  R0, =pwup_x
LDR  R1, =PWUP_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_pwup_x
STR  R1, [R0]
LDR  R0, =pwup_type
MOV  R1, #PWUP_NONE
STR  R1, [R0]
CPC_Done:
POP  {R0-R5, LR}
BX   LR
GreenChainKill:
PUSH {R0-R9, LR}
LDR  R0, =bullet_x
LDR  R8, [R0]
LDR  R0, =bullet_y
LDR  R9, [R0]
LDR  R4, =inv_alive
MOV  R5, #0
MOV  R6, #INV_COUNT
LDR  R7, =9999
GCK_Loop:
CMP  R5, #INV_COUNT
BGE  GCK_Found
LDR  R0, [R4, R5, LSL #2]
CMP  R0, #INV_ALIVE
BNE  GCK_Next
PUSH {R5-R9}
MOV  R0, R5
MOV  R1, #INV_COLS
BL   DivMod
LDR  R2, =inv_offset_x
LDR  R2, [R2]
MOV  R3, #INV_SPACING_X
MUL  R3, R1, R3
ADD  R3, R3, #INV_START_X
ADD  R3, R3, R2
LDR  R2, =inv_offset_y
LDR  R2, [R2]
MOV  R1, #INV_SPACING_Y
MUL  R1, R0, R1
ADD  R1, R1, #INV_START_Y
ADD  R1, R1, R2
SUB  R0, R8, R3
CMP  R0, #0
RSBLT R0, R0, #0
SUB  R2, R9, R1
CMP  R2, #0
RSBLT R2, R2, #0
ADD  R0, R0, R2
POP  {R5-R9}
CMP  R0, R7
BGE  GCK_Next
MOV  R7, R0
MOV  R6, R5
GCK_Next:
ADD  R5, R5, #1
B    GCK_Loop
GCK_Found:
CMP  R6, #INV_COUNT
BGE  GCK_Done
MOV  R0, #INV_EXPLODING
STR  R0, [R4, R6, LSL #2]
LDR  R0, =inv_expl_timer
MOV  R1, #EXPL_FRAMES
STR  R1, [R0, R6, LSL #2]
LDR  R0, =score
LDR  R1, [R0]
ADD  R1, R1, #10
STR  R1, [R0]
GCK_Done:
POP  {R0-R9, LR}
BX   LR
UpdatePowerupTimer:
PUSH {R0-R2, LR}
LDR  R0, =pwup_active
LDR  R1, [R0]
CMP  R1, #PWUP_NONE
BEQ  UPT_Done
LDR  R0, =pwup_timer
LDR  R2, [R0]
SUBS R2, R2, #1
STR  R2, [R0]
BGT  UPT_Done
LDR  R0, =pwup_active
MOV  R1, #PWUP_NONE
STR  R1, [R0]
CMP  R1, #PWUP_RED
BNE  UPT_Done
BL   RefreshSceneAfterPowerup
UPT_Done:
POP  {R0-R2, LR}
BX   LR
DrawPowerupIndicator:
PUSH {R0-R5, LR}
MOV  R0, #157
MOV  R1, #2
MOV  R2, #7
MOV  R3, #7
LDR  R4, =bg_color
LDR  R4, [R4]
BL   DrawRect
LDR  R0, =pwup_active
LDR  R1, [R0]
CMP  R1, #PWUP_NONE
BEQ  DPI_Done
CMP  R1, #PWUP_RED
MOVEQ R2, #COLOR_RED
BEQ  DPI_Draw
CMP  R1, #PWUP_BLUE
MOVEQ R2, #COLOR_BLUE
BEQ  DPI_Draw
CMP  R1, #PWUP_GREEN
MOVEQ R2, #COLOR_GREEN
BEQ  DPI_Draw
LDR  R2, =COLOR_YELLOW
DPI_Draw:
MOV  R0, #158
MOV  R1, #3
MOV  R3, #5
MOV  R4, R2
BL   DrawRect
DPI_Done:
POP  {R0-R5, LR}
BX   LR
RefreshSceneAfterPowerup:
PUSH {R0-R12, LR}
BL   EraseAll
BL   DrawBarriers
BL   DrawAll
BL   DrawPowerup
BL   DrawUI
LDR  R0, =prev_bullet_x
LDR  R1, =BULLET_INACTIVE
STR  R1, [R0]
LDR  R0, =prev_bullet_y
MOV  R1, #0
STR  R1, [R0]
POP  {R0-R12, LR}
BX   LR
